SELECT id, tenant_id, wa_id, phone_number, phone_number_id, waba_id,
       event_type, message_id, message_type, content, direction, send_time,
       ad_campaign_id, ad_set_id, ad_id, crm_lead_id, crm_contact_id,
       status, processing_error, create_time, update_time
FROM crm_whatsapp_webhook_event
WHERE tenant_id = #{tenantId}
  AND message_id = #{messageId}
  AND event_type = #{eventType}
ORDER BY id DESC
LIMIT 1

SELECT id, tenant_id, wa_id, phone_number, phone_number_id, waba_id,
       event_type, message_id, message_type, content, direction, send_time,
       ad_campaign_id, ad_set_id, ad_id, crm_lead_id, crm_contact_id,
       status, processing_error, create_time, update_time
FROM crm_whatsapp_webhook_event
WHERE tenant_id = #{tenantId}

    AND wa_id = #{waId}


    AND status = #{status}


    AND event_type = #{eventType}


    AND phone_number_id = #{phoneNumberId}


    AND send_time >= #{startTime}


    AND send_time <= #{endTime}

ORDER BY create_time DESC
